-- Mall för Projekteringsegenkontroll (styr och övervakning). Kan ändras eller kompletteras i appen
-- (spara en ändrad kontroll som mall), och fler mallar kan läggas till.
INSERT INTO kontrollmall ("Id", "Typ", "Namn", "Beskrivning", "Punkter", "AndradAv") VALUES (
  'b1d5c1e2-6a0f-4f3b-9d55-3c2a7e8f9a10', 'projektering', 'Projekteringsegenkontroll styr och övervakning',
  'Egenkontroll av projekteringen innan handlingarna levereras: underlag, system, komponenter, placering, apparatskåp, samordning och granskning.',
  '["Underlag: Senaste A-, V-, VS-, EL- och RA-handlingar finns, är genomgångna och revisionerna är noterade.", "Underlag: Uppdragsbeskrivning, administrativa föreskrifter och beställarens tekniska krav/styrdokument är genomlästa.", "Underlag: Beställarens krav på beteckningssystem och redovisning (t.ex. BSAB/CoClass, egen standard, BIM-krav) är kända och tillämpade.", "Underlag: Placering av undercentraler och apparatskåp är avstämd med arkitekt och elkonstruktör.", "System: Alla system i V/VS-handlingarna finns med (LB, VS, VP, KB, KV m.fl.) och är redovisade i flödesscheman.", "System: Funktionstexter/driftkort finns för alla system och stämmer med flödesschemana.", "System: Reglerprinciper, börvärden och kurvor är angivna och rimliga.", "System: Larm är beskrivna med larmklass (A/B/C), larmgränser och fördröjningar.", "System: Funktioner vid brand (brandspjäll, brandgasspjäll, fläktstopp/brandgasventilation) är avstämda med brandskyddsdokumentationen.", "System: Tidstyrning, närvarostyrning och behovsstyrning (VAV, CO2, temperatur) är beskrivna.", "System: Energimätning och mätvärdesinsamling uppfyller kraven för uppföljning.", "System: Kommunikation och integrationer (Modbus, BACnet, M-bus, KNX, överordnat system/SCADA) är definierade med ansvarsgränser.", "Komponenter: Komponentlistan är komplett. Alla givare, ställdon, pumpar, fläktar och spjäll har beteckning, typ och placering.", "Komponenter: Signallistan/I/O-listan stämmer mot komponentlistan och funktionstexterna.", "Komponenter: I/O-reserv i undercentralerna uppfyller kravet (t.ex. 20 %).", "Komponenter: Kommunikationsadresser och slingor är planerade utan krockar, och antalet enheter per slinga är kontrollerat.", "Komponenter: Valda produkter uppfyller kravställningen och är miljöbedömda (Byggvarubedömning/Sunda Hus).", "Placering: Placeringsritningarna visar alla komponenter med rätt beteckning, i rätt rum och på rätt plan.", "Placering: Givare är placerade representativt (inte i solljus, nära värmekällor, i drag eller bakom inredning).", "Placering: Åtkomst för service och kalibrering är säkerställd (inspektionsluckor, höjd, fri yta framför skåp).", "Placering: Kabelvägar, genomföringar och brandtätning är samordnade med elkonstruktören.", "Placering: Kraftmatning till apparatskåp och fältutrustning (säkerhetsbrytare, 24 VAC) är dimensionerad.", "Apparatskåp: Skåpen är dimensionerade för utrymme, värmeavgivning, kapslingsklass och reserv.", "Apparatskåp: Kraftberäkning och modulbeläggning är genomförda.", "Apparatskåp: Matning, avsäkring och jordning är avstämda med elkonstruktören.", "Samordning: Samordning med övriga discipliner är genomförd och dokumenterad (protokoll/kollisionskontroll).", "Samordning: Ändringar sedan förra leveransen är markerade (revisionsmoln/ändringsförteckning) och kommunicerade.", "Samordning: Riskanalys för projekteringen är gjord och åtgärderna är införda i handlingarna.", "Granskning: Handlingarna är egenkontrollerade av någon annan än den som upprättat dem.", "Granskning: Handlingarna följer beställarens krav på dokumentförteckning, namngivning, format och leveranssätt.", "Granskning: Projekteringsintyg kan utfärdas för leveransen."]', 'Projekteringsverktyg') ON CONFLICT DO NOTHING;
